for folder in /mnt/03_Video_scrambled_gesture/*; do for file in /mnt/03_Video_scrambled_gesture/$(basename "$folder")/*.mp4; do ffmpeg -i $file -i /mnt/04a_Noised_audiovisual/Noised_audiovisual_bodies/Noised_audiovisual_bodies_SNR_5/$(basename "$folder")/$(basename "${file%.*}").mp4 -map 0:v -map 1:a -c:v copy -ac 2 -shortest -y /mnt/04_Audiovisual_scrambled_gesture/$(basename "$folder")/$(basename "$file"); done; done